package com.bank.qos;

import java.util.logging.Logger;

public class QosClassifier {
    private static final Logger log = Logger.getLogger(QosClassifier.class.getName());

    public String classify(PodResources p) {
        boolean none = p.memRequest < 0 && p.memLimit < 0 && p.cpuRequest < 0 && p.cpuLimit < 0;
            if (none) { log.info(() -> p.name + " -> BestEffort (no requests/limits)");
            return "BestEffort"; }
        boolean guaranteed = p.memRequest >= 0 && p.memRequest == p.memLimit
                && p.cpuRequest >= 0 && p.cpuRequest == p.cpuLimit;
            if (guaranteed) { log.info(() -> p.name + " -> Guaranteed (requests==limits)");
            return "Guaranteed"; }
        log.info(() -> p.name + " -> Burstable (requests<limits)");
        return "Burstable";
    }
}
