package com.bank.qos;

import java.util.*;
import java.util.logging.Logger;

// Evicts under memory pressure: BestEffort first, then Burstable over-request, Guaranteed last.
public class NodeMemoryPressure {
    private static final Logger log = Logger.getLogger(NodeMemoryPressure.class.getName());
    private final QosClassifier qos = new QosClassifier();

    public String evictOne(List<PodResources> pods) {
        Comparator<PodResources> order = Comparator.comparingInt(p -> rank(qos.classify(p), p));
        PodResources victim = pods.stream().max(order).orElseThrow();
        log.severe(() -> "node memory pressure -> EVICT " + victim.name
                + " (" + qos.classify(victim) + ")");
        return victim.name;
    }
    // higher rank = evicted sooner
    private int rank(String q, PodResources p) {
        switch (q) {
            case "BestEffort": return 300;
            case "Burstable":  return p.memUsed > p.memRequest ? 200 : 100; // over-request worse
            default:           return 0; // Guaranteed last
        }
    }
}
