package com.bank.qos;

import java.util.*;
import java.util.logging.Logger;

// emptyDir dies with the Pod; PVC survives reschedule.
public class VolumeLifecycle {
    private static final Logger log = Logger.getLogger(VolumeLifecycle.class.getName());
    private final List<String> emptyDir = new ArrayList<>();
    private final List<String> pvc = new ArrayList<>();

    public void writeEmptyDir(String data) { emptyDir.add(data); pvc.add(data); }

    public void reschedulePod() {
        log.warning("pod rescheduled to a new node -> emptyDir DELETED, PVC re-attached");
        emptyDir.clear();                 // lost with the old Pod
        // pvc keeps its contents (independent lifecycle)
    }
    public List<String> emptyDirContents() { return emptyDir; }
    public List<String> pvcContents() { return pvc; }
}
