package com.bank.qos;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class QosDemo {
    private static final Logger log = Logger.getLogger(QosDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        // Three pods with different QoS
        PodResources report = new PodResources("nightly-report", -1, -1, -1, -1, 900); // BestEffort
        PodResources cache  = new PodResources("statement-cache", 256, 512, 250, 500, 480); // Burstable, over req
        PodResources transfer = new PodResources("transfer-service", 1024, 1024, 500, 500, 700); // Guaranteed

        QosClassifier qos = new QosClassifier();
        qos.classify(report); qos.classify(cache); qos.classify(transfer);

        // Node pressure -> evict in QoS order; Transfer is protected
        NodeMemoryPressure node = new NodeMemoryPressure();
        String evicted = node.evictOne(new ArrayList<>(List.of(report, cache, transfer)));
        log.info("evicted=" + evicted + " (transfer-service protected)");
        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
        log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS on surviving Guaranteed pod");

        // emptyDir vs PVC on reschedule
        VolumeLifecycle vol = new VolumeLifecycle();
        vol.writeEmptyDir("statement-SAV2001-Oct.pdf");
        log.info("before reschedule: emptyDir=" + vol.emptyDirContents() + " pvc=" + vol.pvcContents());
        vol.reschedulePod();
        log.info("after reschedule:  emptyDir=" + vol.emptyDirContents() + " pvc=" + vol.pvcContents());
    }
}
