kind: Deployment
metadata: { name: transfer-service }
spec:
  template:
    spec:
      containers:
        - name: transfer
          image: nbi/transfer-service:v7
          resources:
            requests: { memory: "1Gi", cpu: "500m" }
            limits:   { memory: "1Gi", cpu: "500m" }   # ==requests => Guaranteed
          volumeMounts:
            - { name: scratch, mountPath: /tmp/cache }       # ephemeral
            - { name: ledger,  mountPath: /data/ledger }     # durable
      volumes:
        - name: scratch
          emptyDir: {}                                      # dies with the Pod
        - name: ledger
          persistentVolumeClaim: { claimName: ledger-pvc }  # survives reschedule
